mapper.select:
SELECT p.id, p.points_cost, p.status, p.created_at, c.id AS coupon_id, c.name AS coupon_name, c.coupon_type, c.discount_type, c.remained, c.receive_end, c.per_limit, c.discount_amount, c.discount_rate, c.valid_days, c.total FROM points_mall_item p LEFT JOIN coupon c ON p.coupon_id = c.id
AND c.name LIKE CONCAT('%', #{keyword}, '%')
AND c.discount_type = #{discountType}
p.status = #{status}
ORDER BY p.created_at DESC
